const { booking, settings } = $input.first().json.body;

const itens = (booking.items || []).map((i) => i.name).join(', ');
const periodo = booking.endDate && booking.endDate !== booking.eventDate
  ? `${booking.eventDate} a ${booking.endDate} (${booking.days} dia(s))`
  : booking.eventDate;

const mensagem = `🎉 Nova reserva recebida!\n\nCliente: ${booking.customerName}\nTelefone: ${booking.phone}\nBrinquedos: ${itens}\nPeríodo: ${periodo}\nEndereço: ${booking.address}\nTotal: R$ ${booking.total}\n\nAcesse o painel para confirmar.`;

// Número que deve RECEBER o aviso (o dono do negócio), não o do cliente.
const numeroDono = settings.whatsapp;

return [{ json: { numeroDono, mensagem } }];
